const fs = require('fs');

const file = 'scripts/audit-daily-stock-data-full.js';
let s = fs.readFileSync(file, 'utf8');

// Replace console.table blocks with ASCII-safe output.
// This avoids Unicode box-drawing characters generated by Node console.table.

s = s.replace(
  /console\.table\(\s*worst\.map\(s => \(\{[\s\S]*?\}\)\)\s*\);/,
`console.log(
    worst.map(s =>
      [
        s.code,
        s.rows,
        s.valid,
        s.invalid,
        s.zeroOpen,
        s.zeroHigh,
        s.zeroLow,
        s.zeroClose,
        s.firstDate,
        s.lastDate
      ].join('|')
    ).join('\\n')
  );`
);

s = s.replace(
  /console\.table\(\s*zeroValid\.slice\(0, 100\)\.map\(s => \(\{[\s\S]*?\}\)\)\s*\);/,
`console.log(
    zeroValid.slice(0, 100).map(s =>
      [
        s.code,
        s.rows,
        s.invalid,
        s.zeroOpen,
        s.zeroHigh,
        s.zeroLow,
        s.zeroClose,
        s.firstDate,
        s.lastDate
      ].join('|')
    ).join('\\n')
  );`
);

s = s.replace(
  /console\.table\(\s*worstDates\.map\(\(\[date, count\]\) => \(\{[\s\S]*?\}\)\s*\)\s*\);/,
`console.log(
    worstDates.map(([date, count]) =>
      [date, count].join('|')
    ).join('\\n')
  );`
);

fs.writeFileSync(file, s, 'utf8');

console.log('ASCII-safe audit output patch applied.');
